     3269: TIFFReadDirEntryIfd8Array(TIFF *tif, TIFFDirEntry *direntry, uint64_t **value)
     3270: {
     3271:     enum TIFFReadDirEntryErr err;
     3272:     uint32_t count;
     3273:     void *origdata;
     3274:     uint64_t *data;
