     3297:                 TIFFSwabArrayOfLong8(*value, count);
     3298:             return (TIFFReadDirEntryErrOk);
     3299:         default:
     3300:             break;
     3301:     }
>>>  3302:     data = (uint64_t *)_TIFFmallocExt(tif, count * 8);
